{"command":"create","path":"/workspace/backend/internal/db/db.go","file_text":"package db

import (
	"context"
	"embed"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

//go:embed schema.sql
var schemaFS embed.FS

type DB struct {
	Pool  *pgxpool.Pool
	Mongo *mongo.Client
	MongoDB *mongo.Database
}

func Connect(ctx context.Context, databaseURL, mongoURI string) (*DB, error) {
	cfg, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		return nil, fmt.Errorf("parse db url: %w", err)
	}
	cfg.MaxConns = 20
	cfg.MinConns = 2
	cfg.MaxConnLifetime = time.Hour
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("pg connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mclient, err := mongo.Connect(options.Client().ApplyURI(mongoURI))
	if err != nil {
		pool.Close()
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	mctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := mclient.Ping(mctx, nil); err != nil {
		pool.Close()
		_ = mclient.Disconnect(context.Background())
		return nil, fmt.Errorf("mongo ping: %w", err)
	}

	return &DB{Pool: pool, Mongo: mclient, MongoDB: mclient.Database("arena")}, nil
}

func (d *DB) Close() {
	if d.Pool != nil {
		d.Pool.Close()
	}
	if d.Mongo != nil {
		_ = d.Mongo.Disconnect(context.Background())
	}
}

func (d *DB) Migrate(ctx context.Context) error {
	sqlBytes, err := schemaFS.ReadFile("schema.sql")
	if err != nil {
		return err
	}
	_, err = d.Pool.Exec(ctx, string(sqlBytes))
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	// Materialize MongoDB collections and indexes
	colls := []string{"audit_archive", "event_archive", "notes"}
	for _, name := range colls {
		_ = d.MongoDB.CreateCollection(ctx, name)
	}
	audit := d.MongoDB.Collection("audit_archive")
	_, _ = audit.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: map[string]int{"entityType": 1, "entityId": 1}},
		{Keys: map[string]int{"occurredAt": -1}},
		{Keys: map[string]int{"actorId": 1}},
		{Keys: map[string]int{"action": 1}},
	})
	events := d.MongoDB.Collection("event_archive")
	_, _ = events.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: map[string]int{"createdAt": -1}},
		{Keys: map[string]int{"entityType": 1, "entityId": 1}},
	})
	return nil
}

func (d *DB) Reset(ctx context.Context) error {
	tables := []string{
		"worker_location_updates", "handling_checkpoints", "disruptions",
		"serviceability_snapshots", "realtime_events", "idempotency_keys",
		"timeline_events", "audit_log", "capacity_reservations", "handoffs",
		"assignments", "journey_stops", "journeys", "samples", "lab_acceptances",
		"connections", "locations", "sample_types", "sessions", "users",
		"network_meta", "meta",
	}
	for _, t := range tables {
		if _, err := d.Pool.Exec(ctx, "DROP TABLE IF EXISTS "+t+" CASCADE"); err != nil {
			return err
		}
	}
	_ = d.MongoDB.Collection("audit_archive").Drop(ctx)
	_ = d.MongoDB.Collection("event_archive").Drop(ctx)
	_ = d.MongoDB.Collection("notes").Drop(ctx)
	return d.Migrate(ctx)
}

func (d *DB) WithTx(ctx context.Context, fn func(pgx.Tx) error) error {
	tx, err := d.Pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}
"}

{"command":"create","path":"/workspace/backend/internal/auth/auth.go","file_text":"package auth

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

func HashPassword(password string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	return string(b), err
}

func CheckPassword(hash, password string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(password)) == nil
}

func NewToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func BearerToken(r *http.Request) (string, error) {
	h := r.Header.Get("Authorization")
	if h == "" {
		return "", errors.New("missing authorization")
	}
	parts := strings.SplitN(h, " ", 2)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") || parts[1] == "" {
		return "", errors.New("invalid authorization")
	}
	return parts[1], nil
}

func SessionExpiry() time.Time {
	return time.Now().UTC().Add(24 * time.Hour)
}
"}

{"command":"create","path":"/workspace/backend/internal/httpapi/errors.go","file_text":"package httpapi

import (
	"encoding/json"
	"net/http"
)

type APIError struct {
	Status int
	Code   string
	Msg    string
}

func (e *APIError) Error() string { return e.Code + ": " + e.Msg }

func E(status int, code, msg string) *APIError {
	return &APIError{Status: status, Code: code, Msg: msg}
}

func WriteError(w http.ResponseWriter, err error) {
	if ae, ok := err.(*APIError); ok {
		WriteJSON(w, ae.Status, map[string]string{"error": ae.Msg, "code": ae.Code})
		return
	}
	WriteJSON(w, 500, map[string]string{"error": "internal error", "code": "internal_error"})
}

func WriteJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func WriteData(w http.ResponseWriter, status int, data interface{}) {
	WriteJSON(w, status, map[string]interface{}{"data": data})
}

func DecodeJSON(r *http.Request, dst interface{}) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return E(400, "invalid_json", "invalid json body")
	}
	return nil
}

var (
	ErrUnauthorized       = E(401, "unauthorized", "unauthorized")
	ErrForbidden          = E(403, "forbidden", "forbidden")
	ErrNotFound           = E(404, "not_found", "not found")
	ErrRoleNotSelected    = E(409, "role_not_selected", "active role not selected")
	ErrInvalidCredentials = E(401, "invalid_credentials", "invalid credentials")
	ErrConcurrent         = E(409, "concurrent_conflict", "concurrent conflict")
	ErrIdempotencyReq     = E(400, "idempotency_required", "idempotency key required")
	ErrIdempotencyConflict = E(409, "idempotency_conflict", "idempotency conflict")
)
"}

{"command":"create","path":"/workspace/backend/internal/app/util.go","file_text":"package app

import (
	"encoding/json"
	"math"
	"time"

	"github.com/google/uuid"
)

func NewID() string { return uuid.NewString() }

func Ptr[T any](v T) *T { return &v }

func Now() time.Time { return time.Now().UTC() }

func ParseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, nil
	}
	formats := []string{
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05",
		"2006-01-02 15:04:05",
	}
	var err error
	var t time.Time
	for _, f := range formats {
		t, err = time.Parse(f, s)
		if err == nil {
			return t.UTC(), nil
		}
	}
	return time.Time{}, err
}

func MustJSON(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func FromJSON[T any](b []byte) T {
	var v T
	_ = json.Unmarshal(b, &v)
	return v
}

func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	toRad := func(d float64) float64 { return d * math.Pi / 180 }
	dLat := toRad(lat2 - lat1)
	dLon := toRad(lon2 - lon1)
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(toRad(lat1))*math.Cos(toRad(lat2))*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func ContainsStr(ss []string, s string) bool {
	for _, x := range ss {
		if x == s {
			return true
		}
	}
	return false
}

func FormatTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func FormatTimePtr(t *time.Time) interface{} {
	if t == nil || t.IsZero() {
		return nil
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func RoleOK(role string) bool {
	switch role {
	case "administrator", "dispatcher", "requester", "collection_professional",
		"delivery_partner", "node_handler", "laboratory_team":
		return true
	}
	return false
}

func DefaultActiveRole(roles []string) string {
	if len(roles) == 1 {
		return roles[0]
	}
	// Prefer administrator if present for bootstrap convenience when single-purpose
	if len(roles) == 0 {
		return ""
	}
	return ""
}
"}

