	DB     *db.DB
	mu     sync.Mutex
	subs   map[chan models.RealtimeEvent]struct{}
	ready  bool
}

func New(cfg Config) (*App, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	d, err := db.Connect(ctx, cfg.DatabaseURL, cfg.MongoURI)
	if err != nil {
		return nil, err
	}
	a := &App{Cfg: cfg, DB: d, subs: map[chan models.RealtimeEvent]struct{}{}}
	return a, nil
}

func (a *App) Close() {
	a.DB.Close()
}

func (a *App) Bootstrap(ctx context.Context) error {
	if err := a.DB.Migrate(ctx); err != nil {
		return err
	}
	if err := a.ensureAdmin(ctx); err != nil {
		return err
	}
	if err := a.ensureDefaultSampleTypes(ctx); err != nil {
		return err
	}
	if err := a.ensureServiceabilitySnapshot(ctx); err != nil {
		return err
	}
	a.ready = true
	go a.offerExpiryLoop()
	log.Printf("bootstrap complete")
	return nil
}

func (a *App) ensureAdmin(ctx context.Context) error {
	var n int
	err := a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n)
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	hash, err := auth.HashPassword(a.Cfg.AdminPassword)
	if err != nil {
		return err
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO users (id, username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES ($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7::jsonb,true)`,
		id, a.Cfg.AdminUsername, hash, "Administrator",
		MustJSON([]string{models.RoleAdministrator}),
		MustJSON([]string{}),
		MustJSON([]models.Certification{}),
	)
	return err
}

func (a *App) ensureDefaultSampleTypes(ctx context.Context) error {
	var n int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM sample_types`).Scan(&n)
	if n > 0 {
		return nil
	}
	defaults := []struct {
		name, qual, container string
		minT, maxT            float64
		cooled, batch         bool
	}{
		{"Amber", "Amber", "standard", 2, 25, false, true},
		{"Indigo", "Indigo", "standard", 2, 25, false, true},
		{"Frost", "Frost", "cooled", 2, 8, true, true},
		{"Pulse", "Pulse", "standard", 2, 25, false, false},
	}
	// Create first without incompatibilities, then set Indigo incompatible with Amber
	ids := map[string]string{}
	for _, d := range defaults {
		id := NewID()
		ids[d.name] = id
		_, err := a.DB.Pool.Exec(ctx, `
			INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
				container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
				requires_cooled_route, batching_allowed)
			VALUES ($1,$2,true,$3,$4,$5,$6,'[]'::jsonb,$7,$8)`,
			id, d.name, d.qual, d.container, d.minT, d.maxT, d.cooled, d.batch)
		if err != nil {
			return err
		}
	}
	// Indigo must not share with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok2 := ids["Indigo"]; ok2 {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE sample_types SET incompatible_sample_types = $1::jsonb WHERE id = $2`,
				MustJSON([]string{amber}), indigo)
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE sample_types SET incompatible_sample_types = $1::jsonb WHERE id = $2`,
				MustJSON([]string{indigo}), amber)
		}
	}
	return nil
}

func (a *App) ensureServiceabilitySnapshot(ctx context.Context) error {
	var ver int
	err := a.DB.Pool.QueryRow(ctx, `SELECT current_serviceability_version FROM network_meta WHERE id=1`).Scan(&ver)
	if err != nil {
		return err
	}
	if ver == 0 {
		return a.recomputeServiceability(ctx)
	}
	return nil
}

func (a *App) offerExpiryLoop() {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()
	for range ticker.C {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		_ = a.expireOffers(ctx)
		cancel()
	}
}

func (a *App) IsReady() bool {
	if !a.ready {
		return false
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := a.DB.Pool.Ping(ctx); err != nil {
		return false
	}
	if err := a.DB.Mongo.Ping(ctx, nil); err != nil {
		return false
	}
	return true
}

func (a *App) Router() http.Handler {
	mux := http.NewServeMux()
	a.registerRoutes(mux)
	return a.withMiddleware(mux)
}
"}

{"command":"create","path":"/workspace/backend/internal/app/middleware.go","file_text":"package app

import (
	"context"
	"net/http"
	"strings"
	"time"

	"labsample/internal/auth"
	"labsample/internal/httpapi"
	"labsample/internal/models"
)

type ctxKey int

const (
	ctxSession ctxKey = iota
	ctxUser
)

type SessionInfo struct {
	Token      string
	UserID     string
	ActiveRole string
	Roles      []string
}

func (a *App) withMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		// Public endpoints
		if r.URL.Path == "/ready" || r.URL.Path == "/api/authenticate-user" ||
			strings.HasPrefix(r.URL.Path, "/map/") || r.URL.Path == "/" ||
			strings.HasPrefix(r.URL.Path, "/assets/") || r.URL.Path == "/index.html" ||
			!strings.HasPrefix(r.URL.Path, "/api/") {
			next.ServeHTTP(w, r)
			return
		}
		token, err := auth.BearerToken(r)
		if err != nil {
			httpapi.WriteError(w, httpapi.ErrUnauthorized)
			return
		}
		sess, user, err := a.loadSession(r.Context(), token)
		if err != nil {
			httpapi.WriteError(w, httpapi.ErrUnauthorized)
			return
		}
		ctx := context.WithValue(r.Context(), ctxSession, sess)
		ctx = context.WithValue(ctx, ctxUser, user)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func (a *App) loadSession(ctx context.Context, token string) (*SessionInfo, *models.User, error) {
	var s SessionInfo
	var rolesJSON []byte
	var exp time.Time
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT token, user_id, active_role, roles, expires_at FROM sessions WHERE token=$1`, token).
		Scan(&s.Token, &s.UserID, &s.ActiveRole, &rolesJSON, &exp)
	if err != nil {
		return nil, nil, err
	}
	if time.Now().UTC().After(exp) {
		return nil, nil, httpapi.ErrUnauthorized
	}
	s.Roles = FromJSON[[]string](rolesJSON)
	u, err := a.getUser(ctx, s.UserID)
	if err != nil || !u.Active {
		return nil, nil, httpapi.ErrUnauthorized
	}
	return &s, u, nil
}

func SessionFrom(ctx context.Context) *SessionInfo {
	v, _ := ctx.Value(ctxSession).(*SessionInfo)
	return v
}

func UserFrom(ctx context.Context) *models.User {
	v, _ := ctx.Value(ctxUser).(*models.User)
	return v
}

func (a *App) requireRole(ctx context.Context, roles ...string) (*SessionInfo, *models.User, error) {
	s := SessionFrom(ctx)
	u := UserFrom(ctx)
	if s == nil || u == nil {
		return nil, nil, httpapi.ErrUnauthorized
	}
	if s.ActiveRole == "" {
		return nil, nil, httpapi.ErrRoleNotSelected
	}
	if len(roles) == 0 {
		return s, u, nil
	}
	for _, r := range roles {
		if s.ActiveRole == r {
			return s, u, nil
		}
	}
	// administrator can do dispatcher things when acting as administrator for admin-only;
	// but contract says permissions use selected role. So we enforce exact match.
	return nil, nil, httpapi.ErrForbidden
}

func (a *App) requireAnyRole(ctx context.Context, roles ...string) (*SessionInfo, *models.User, error) {
	return a.requireRole(ctx, roles...)
}

func (a *App) requireAdminOrDispatcher(ctx context.Context) (*SessionInfo, *models.User, error) {
	return a.requireRole(ctx, models.RoleAdministrator, models.RoleDispatcher)
}

func (a *App) requireAdmin(ctx context.Context) (*SessionInfo, *models.User, error) {
	return a.requireRole(ctx, models.RoleAdministrator)
}
"}

{"command":"create","path":"/workspace/backend/internal/app/users.go","file_text":"package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5"
	"labsample/internal/auth"
	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) getUser(ctx context.Context, id string) (*models.User, error) {
	u := &models.User{}
	var roles, quals, certs []byte
	var assigned *string
	var penalty *time.Time
	var lat, lon *float64
	var locAt *time.Time
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications,
			active, assigned_location_id, available, capacity_units, decline_penalty_until,
			latest_lat, latest_lon, location_recorded_at, created_at
		FROM users WHERE id=$1`, id).Scan(
		&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&roles, &quals, &certs, &u.Active, &assigned, &u.Available, &u.CapacityUnits,
		&penalty, &lat, &lon, &locAt, &u.CreatedAt,
	)
	if err != nil {
		return nil, err
	}
	u.Roles = FromJSON[[]string](roles)
	u.Qualifications = FromJSON[[]string](quals)
	u.Certifications = FromJSON[[]models.Certification](certs)
	u.AssignedLocationID = assigned
	u.DeclinePenaltyUntil = penalty
	u.LatestLat = lat
	u.LatestLon = lon
	u.LocationRecordedAt = locAt
	return u, nil
}

func (a *App) getUserByUsername(ctx context.Context, username string) (*models.User, error) {
	var id string
	err := a.DB.Pool.QueryRow(ctx, `SELECT id FROM users WHERE username=$1`, username).Scan(&id)
	if err != nil {
		return nil, err
	}
	return a.getUser(ctx, id)
}

func (a *App) userJSON(u *models.User) map[string]interface{} {
	out := map[string]interface{}{
		"userId":         u.ID,
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": certsJSON(u.Certifications),
		"active":         u.Active,
	}
	if u.Email != "" {
		out["email"] = u.Email
	}
	if u.FullName != "" {
		out["fullName"] = u.FullName
	}
	if u.Phone != "" {
		out["phone"] = u.Phone
	}
	return out
}

func certsJSON(cs []models.Certification) []map[string]interface{} {
	out := make([]map[string]interface{}, 0, len(cs))
	for _, c := range cs {
		m := map[string]interface{}{"code": c.Code, "active": c.Active}
		if c.ExpiresAt != nil {
			m["expiresAt"] = FormatTime(*c.ExpiresAt)
		}
		out = append(out, m)
	}
	return out
}

func (a *App) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	u, err := a.getUserByUsername(r.Context(), req.Username)
	if err != nil || !auth.CheckPassword(u.PasswordHash, req.Password) || !u.Active {
		httpapi.WriteError(w, httpapi.ErrInvalidCredentials)
		a.audit(r.Context(), "", "", "authenticate_user", "user", req.Username, false, map[string]interface{}{"reason": "invalid_credentials"})
		return
	}
	token, err := auth.NewToken()
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "token error"))
		return
	}
	active := DefaultActiveRole(u.Roles)
	exp := auth.SessionExpiry()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO sessions (token, user_id, active_role, roles, expires_at) VALUES ($1,$2,$3,$4::jsonb,$5)`,
		token, u.ID, active, MustJSON(u.Roles), exp)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "session error"))
		return
	}
	a.audit(r.Context(), u.ID, active, "authenticate_user", "user", u.ID, true, nil)
	httpapi.WriteData(w, 200, map[string]interface{}{
		"sessionToken": token,
		"userId":       u.ID,
		"roles":        u.Roles,
		"activeRole":   active,
	})
}

func (a *App) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	s := SessionFrom(r.Context())
	u := UserFrom(r.Context())
	if s == nil || u == nil {
		httpapi.WriteError(w, httpapi.ErrUnauthorized)
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	if !ContainsStr(u.Roles, req.Role) || !RoleOK(req.Role) {
		httpapi.WriteError(w, httpapi.ErrForbidden)
		return
	}
	_, err := a.DB.Pool.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, s.Token)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "update failed"))
		return
	}
	a.audit(r.Context(), u.ID, req.Role, "select_active_role", "user", u.ID, true, map[string]interface{}{"role": req.Role})
	httpapi.WriteData(w, 200, map[string]interface{}{
		"activeRole": req.Role,
		"roles":      u.Roles,
	})
}

func (a *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		httpapi.WriteError(w, err)
		return
	}
	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              string                 `json:"email"`
		FullName           string                 `json:"fullName"`
		Phone              string                 `json:"phone"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		httpapi.WriteError(w, httpapi.E(400, "invalid_json", "missing required fields"))
		return
	}
	for _, role := range req.Roles {
		if !RoleOK(role) {
			httpapi.WriteError(w, httpapi.E(400, "invalid_json", "invalid role"))
			return
		}
	}
	if req.Qualifications == nil {
		req.Qualifications = []string{}
	}
	if req.Certifications == nil {
		req.Certifications = []models.Certification{}
	}
	for _, c := range req.Certifications {
		if c.Code == "" {
			httpapi.WriteError(w, httpapi.E(400, "invalid_certification", "invalid certification"))
			return
		}
	}
	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "hash failed"))
		return
	}
	id := NewID()
	_, err = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO users (id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9::jsonb,$10,$11)`,
		id, req.Username, hash, req.Email, req.FullName, req.Phone,
		MustJSON(req.Roles), MustJSON(req.Qualifications), MustJSON(req.Certifications),
		req.Active, req.AssignedLocationID)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(409, "concurrent_conflict", "username may already exist"))
		return
	}
	u, _ := a.getUser(r.Context(), id)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "create_user", "user", id, true, nil)
	httpapi.WriteData(w, 201, a.userJSON(u))
}

func (a *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdmin(r.Context())
	if err != nil {
		httpapi.WriteError(w, err)
		return
	}
	var req struct {
		UserID             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	u, err := a.getUser(r.Context(), req.UserID)
	if err != nil {
		httpapi.WriteError(w, httpapi.ErrNotFound)
		return
	}
	if req.Qualifications == nil {
		req.Qualifications = u.Qualifications
	}
	if req.Certifications == nil {
		req.Certifications = u.Certifications
	}
	for _, c := range req.Certifications {
		if c.Code == "" {
			httpapi.WriteError(w, httpapi.E(400, "invalid_certification", "invalid certification"))
			return
		}
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE users SET roles=$1::jsonb, qualifications=$2::jsonb, certifications=$3::jsonb, active=$4, assigned_location_id=$5
		WHERE id=$6`,
		MustJSON(req.Roles), MustJSON(req.Qualifications), MustJSON(req.Certifications),
		req.Active, req.AssignedLocationID, req.UserID)
	if err != nil {
		httpapi.WriteError(w, httpapi.E(500, "internal_error", "update failed"))
		return
	}
	u, _ = a.getUser(r.Context(), req.UserID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "update_user_access", "user", req.UserID, true, nil)
	httpapi.WriteData(w, 201, a.userJSON(u))
}

func (a *App) handleReadUser(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context())
	if err != nil {
		// allow any authenticated with role; if role not selected still allow self read? contract needs role
		httpapi.WriteError(w, err)
		return
	}
	userID := r.PathValue("userId")
	if s.ActiveRole != models.RoleAdministrator && s.ActiveRole != models.RoleDispatcher && me.ID != userID {
		httpapi.WriteError(w, httpapi.ErrForbidden)
		return
	}
	u, err := a.getUser(r.Context(), userID)
	if err != nil {
		httpapi.WriteError(w, httpapi.ErrNotFound)
		return
	}
	httpapi.WriteData(w, 200, a.userJSON(u))
}

func (a *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleAdministrator, models.RoleDispatcher,
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam)
	if err != nil {
		httpapi.WriteError(w, err)
		return
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := httpapi.DecodeJSON(r, &req); err != nil {
		httpapi.WriteError(w, err)
		return
	}
	if s.ActiveRole != models.RoleAdministrator && s.ActiveRole != models.RoleDispatcher && me.ID != req.WorkerID {
		httpapi.WriteError(w, httpapi.ErrForbidden)
		return
	}
	_, err = a.DB.Pool.Exec(r.Context(), `UPDATE users SET available=$1, capacity_units=$2 WHERE id=$3`,
		req.Available, req.CapacityUnits, req.WorkerID)
	if err != nil {
		httpapi.WriteError(w, httpapi.ErrNotFound)
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "set_worker_availability", "user", req.WorkerID, true, nil)
	httpapi.WriteData(w, 200, map[string]interface{}{
		"workerId": req.WorkerID, "available": req.Available, "capacityUnits": req.CapacityUnits,
	})
}

// silence unused imports if any
var _ = json.Marshal
var _ = pgx.ErrNoRows
"}

{"command":"create","path":"/workspace/backend/internal/app/audit.go","file_text":"package app

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"labsample/internal/models"
)

func (a *App) audit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	id := NewID()
	now := Now()
	var actor interface{}
	if actorID != "" {
		actor = actorID
	}
	_, _ = a.DB.Pool.Exec(ctx, `
		INSERT INTO audit_log (id, actor_id, actor_role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb)`,
		id, actor, role, action, entityType, entityID, success, now, MustJSON(details))
	_, _ = a.DB.Pool.Exec(ctx, `
		INSERT INTO timeline_events (action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb)`,
		action, actor, role, entityType, entityID, success, now, MustJSON(details))
	// Mongo archive
	_, _ = a.DB.MongoDB.Collection("audit_archive").InsertOne(ctx, bson.M{
		"auditId": id, "actorId": actorID, "actorRole": role, "role": role,
		"action": action, "entityType": entityType, "entityId": entityID,
		"success": success, "occurredAt": now, "details": details,
	})
	a.publishEvent(ctx, action, entityType, entityID, details)
}

func (a *App) publishEvent(ctx context.Context, typ, entityType, entityID string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	var id int64
	_ = a.DB.Pool.QueryRow(ctx, `
		INSERT INTO realtime_events (type, entity_type, entity_id, payload)
		VALUES ($1,$2,$3,$4::jsonb) RETURNING id`, typ, entityType, entityID, MustJSON(payload)).Scan(&id)
	ev := models.RealtimeEvent{
		ID: id, Type: typ, EntityType: entityType, EntityID: entityID,
		Payload: payload, CreatedAt: Now(),
	}
	a.mu.Lock()
	for ch := range a.subs {
		select {
		case ch <- ev:
		default:
		}
	}
	a.mu.Unlock()
}

func (a *App) subscribe() chan models.RealtimeEvent {
	ch := make(chan models.RealtimeEvent, 32)
	a.mu.Lock()
	a.subs[ch] = struct{}{}
	a.mu.Unlock()
	return ch
}

func (a *App) unsubscribe(ch chan models.RealtimeEvent) {
	a.mu.Lock()
	delete(a.subs, ch)
	a.mu.Unlock()
	close(ch)
}

func (a *App) getTimeline(ctx context.Context, entityType, entityID string) ([]models.TimelineEntry, error) {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, action, COALESCE(actor_id::text,''), role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY id ASC`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []models.TimelineEntry
	for rows.Next() {
		var e models.TimelineEntry
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
			return nil, err
		}
		e.Details = FromJSON[map[string]interface{}](details)
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		out = append(out, e)
	}
	if out == nil {
		out = []models.TimelineEntry{}
	}
	return out, nil
}

func (a *App) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = s
	var req struct {
		Query      string  `json:"query"`
		ActorID    *string `json:"actorId"`
		EntityType *string `json:"entityType"`
		EntityID   *string `json:"entityId"`
		Action     *string `json:"action"`
		Role       *string `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      int     `json:"limit"`
		Offset     int     `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Limit <= 0 {
		req.Limit = 500
	}
	if req.Limit > 5000 {
		req.Limit = 5000
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	q := `SELECT id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE 1=1`
	args := []interface{}{}
	n := 1
	add := func(clause string, v interface{}) {
		q += clause
		args = append(args, v)
		n++
	}
	if req.ActorID != nil {
		add(` AND actor_id=$`+itoa(n), *req.ActorID)
	}
	if req.EntityType != nil {
		add(` AND entity_type=$`+itoa(n), *req.EntityType)
	}
	if req.EntityID != nil {
		add(` AND entity_id=$`+itoa(n), *req.EntityID)
	}
	if req.Action != nil {
		add(` AND action=$`+itoa(n), *req.Action)
	}
	if req.Role != nil {
		add(` AND actor_role=$`+itoa(n), *req.Role)
	}
	if req.Success != nil {
		add(` AND success=$`+itoa(n), *req.Success)
	}
	if req.FromTime != nil {
		if t, err := ParseTime(*req.FromTime); err == nil {
			add(` AND occurred_at >= $`+itoa(n), t)
		}
	}
	if req.ToTime != nil {
		if t, err := ParseTime(*req.ToTime); err == nil {
			add(` AND occurred_at <= $`+itoa(n), t)
		}
	}
	if req.Query != "" {
		add(` AND (action ILIKE $`+itoa(n)+` OR entity_id ILIKE $`+itoa(n)+` OR entity_type ILIKE $`+itoa(n)+` OR details::text ILIKE $`+itoa(n)+`)`, "%"+req.Query+"%")
	}
	countQ := `SELECT COUNT(*) FROM (` + q + `) c`
	var total int
	_ = a.DB.Pool.QueryRow(r.Context(), countQ, args...).Scan(&total)
	order := " ORDER BY occurred_at DESC, id DESC"
	if req.Order == "oldest_first" {
		order = " ORDER BY occurred_at ASC, id ASC"
	}
	q += order + ` LIMIT $` + itoa(n) + ` OFFSET $` + itoa(n+1)
	args = append(args, req.Limit, req.Offset)
	rows, err := a.DB.Pool.Query(r.Context(), q, args...)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	defer rows.Close()
	entries := []map[string]interface{}{}
	for rows.Next() {
		var id, actorID, role, action, et, eid string
		var success bool
		var at time.Time
		var details []byte
		if err := rows.Scan(&id, &actorID, &role, &action, &et, &eid, &success, &at, &details); err != nil {
			continue
		}
		d := FromJSON[map[string]interface{}](details)
		if d == nil {
			d = map[string]interface{}{}
		}
		entries = append(entries, map[string]interface{}{
			"auditId": id, "actorId": actorID, "role": role, "actorRole": role,
			"action": action, "entityType": et, "entityId": eid,
			"success": success, "occurredAt": FormatTime(at), "details": d,
		})
	}
	returned := len(entries)
	hasMore := req.Offset+returned < total
	result := map[string]interface{}{
		"entries": entries, "total": total, "returned": returned,
		"offset": req.Offset, "limit": req.Limit, "order": req.Order, "hasMore": hasMore,
	}
	if hasMore {
		result["nextOffset"] = req.Offset + returned
	}
	writeData(w, 200, result)
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	s := ""
	for i > 0 {
		s = string(rune('0'+i%10)) + s
		i /= 10
	}
	return s
}
"}

