func (a *App) bumpNetworkRevision(ctx context.Context) error {
	_, err := a.DB.Pool.Exec(ctx, `UPDATE network_meta SET revision = revision + 1 WHERE id=1`)
	if err != nil {
		return err
	}
	return a.recomputeServiceability(ctx)
}

func (a *App) recomputeServiceability(ctx context.Context) error {
	var rev int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT revision FROM network_meta WHERE id=1`).Scan(&rev)
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, name, latitude, longitude, coverage_km FROM locations
		WHERE active=true AND fn_collection_point=true`)
	if err != nil {
		return err
	}
	defer rows.Close()
	regions := []models.ServiceabilityRegion{}
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return err
		}
		regions = append(regions, r)
	}
	var ver int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots`).Scan(&ver)
	ver++
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$2,$3,$4::jsonb,$5)`,
		ver, time.Now().UTC(), rev, MustJSON(regions), len(regions))
	if err != nil {
		return err
	}
	_, err = a.DB.Pool.Exec(ctx, `UPDATE network_meta SET current_serviceability_version=$1 WHERE id=1`, ver)
	return err
}

func (a *App) currentServiceabilityVersion(ctx context.Context) int {
	var v int
	_ = a.DB.Pool.QueryRow(ctx, `SELECT current_serviceability_version FROM network_meta WHERE id=1`).Scan(&v)
	if v < 1 {
		v = 1
	}
	return v
}

func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if _, _, err := a.requireRole(r.Context()); err != nil {
		writeErr(w, err)
		return
	}
	var req struct{}
	_ = decode(r, &req)
	var ver, rev, count int
	var status string
	var computed time.Time
	var regionsJSON []byte
	err := a.DB.Pool.QueryRow(r.Context(), `
		SELECT s.version, s.status, s.computed_at, s.network_revision, s.regions, s.active_collection_point_count
		FROM serviceability_snapshots s
		JOIN network_meta m ON m.current_serviceability_version = s.version
		WHERE m.id=1`).Scan(&ver, &status, &computed, &rev, &regionsJSON, &count)
	if err != nil {
		// empty snapshot
		writeData(w, 200, map[string]interface{}{
			"version": 1, "status": "complete", "computedAt": FormatTime(Now()),
			"networkRevision": 0, "regions": []interface{}{}, "activeCollectionPointCount": 0,
		})
		return
	}
	regions := FromJSON[[]models.ServiceabilityRegion](regionsJSON)
	if regions == nil {
		regions = []models.ServiceabilityRegion{}
	}
	writeData(w, 200, map[string]interface{}{
		"version": ver, "status": status, "computedAt": FormatTime(computed),
		"networkRevision": rev, "regions": regions, "activeCollectionPointCount": count,
	})
}
"}

{"command":"create","path":"/workspace/backend/internal/app/serviceability.go","file_text":"package app

import (
	"context"
	"math"
	"sort"
	"time"

	"labsample/internal/models"
)

type routeHop struct {
	ConnectionID   string
	FromLocationID string
	ToLocationID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
}

type plannedRoute struct {
	CollectionNode *models.Location
	Laboratory     *models.Location
	Hops           []routeHop
	TotalMinutes   int
	TotalCost      float64
	ArrivalAt      time.Time
	Reason         string
	Serviceable    bool
}

type serviceabilityInput struct {
	Origin               models.Coordinate
	OriginType           string
	OriginNodeID         *string
	SampleTypeID         string
	RequestedAt          time.Time
	DeliveryDeadline     time.Time
	EarliestCollectionAt time.Time
	LatestCollectionAt   time.Time
	RequiresCooled       bool
	BatchingAllowed      bool
}

func (a *App) checkServiceability(ctx context.Context, in serviceabilityInput) (*plannedRoute, string, int) {
	ver := a.currentServiceabilityVersion(ctx)
	st, err := a.getSampleType(ctx, in.SampleTypeID)
	if err != nil {
		return &plannedRoute{Reason: "handling_rules_unsatisfiable"}, "handling_rules_unsatisfiable", ver
	}
	requiresCooled := st.RequiresCooledRoute || in.RequiresCooled

	// Find collection nodes within coverage (max 5km of active collection points)
	nodes, err := a.listActiveCollectionNodes(ctx)
	if err != nil || len(nodes) == 0 {
		return &plannedRoute{Reason: "outside_service_coverage"}, "outside_service_coverage", ver
	}

	var candidates []struct {
		node *models.Location
		dist float64
	}
	if in.OriginType == "node" && in.OriginNodeID != nil {
		for _, n := range nodes {
			if n.ID == *in.OriginNodeID {
				candidates = append(candidates, struct {
					node *models.Location
					dist float64
				}{n, 0})
			}
		}
	} else {
		for _, n := range nodes {
			d := HaversineKm(in.Origin.Latitude, in.Origin.Longitude, n.Coordinate.Latitude, n.Coordinate.Longitude)
			limit := n.CoverageKm
			if limit > 5 {
				limit = 5
			}
			if d <= limit+1e-9 {
				candidates = append(candidates, struct {
					node *models.Location
					dist float64
				}{n, d})
			}
		}
	}
	if len(candidates) == 0 {
		return &plannedRoute{Reason: "outside_service_coverage"}, "outside_service_coverage", ver
	}
	sort.Slice(candidates, func(i, j int) bool { return candidates[i].dist < candidates[j].dist })

	labs, err := a.listAcceptingLaboratories(ctx, in.SampleTypeID)
	if err != nil || len(labs) == 0 {
		return &plannedRoute{Reason: "no_accepting_laboratory"}, "no_accepting_laboratory", ver
	}

	conns, err := a.listActiveConnections(ctx)
	if err != nil {
		return &plannedRoute{Reason: "no_route"}, "no_route", ver
	}

	var best *plannedRoute
	for _, cand := range candidates {
		for _, lab := range labs {
			route := a.findRoute(cand.node, lab, conns, requiresCooled)
			if route == nil {
				continue
			}
			// capacity check along route + nodes/lab
			if !a.routeHasCapacity(ctx, route, requiresCooled) {
				if best == nil {
					best = &plannedRoute{Reason: "insufficient_capacity"}
				}
				continue
			}
			start := in.EarliestCollectionAt
			if start.Before(in.RequestedAt) {
				start = in.RequestedAt
			}
			// travel from origin to collection node ~ distance based estimate 2 min/km + handling
			toNodeMin := int(math.Ceil(cand.dist * 3))
			if toNodeMin < 1 && cand.dist > 0 {
				toNodeMin = 1
			}
			total := toNodeMin + cand.node.HandlingMinutes + route.TotalMinutes + lab.HandlingMinutes
			arrival := start.Add(time.Duration(total) * time.Minute)
			if arrival.After(in.DeliveryDeadline) {
				if best == nil || best.Reason == "" {
					best = &plannedRoute{Reason: "deadline_unreachable"}
				}
				continue
			}
			route.CollectionNode = cand.node
			route.Laboratory = lab
			route.ArrivalAt = arrival
			route.TotalMinutes = total
			route.Serviceable = true
			route.Reason = "serviceable"
			if best == nil || !best.Serviceable || route.TotalCost < best.TotalCost ||
				(route.TotalCost == best.TotalCost && route.TotalMinutes < best.TotalMinutes) {
				cp := *route
				best = &cp
			}
		}
	}
	if best == nil {
		return &plannedRoute{Reason: "no_route"}, "no_route", ver
	}
	if !best.Serviceable {
		return best, best.Reason, ver
	}
	return best, "serviceable", ver
}

func (a *App) listActiveCollectionNodes(ctx context.Context) ([]*models.Location, error) {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id FROM locations WHERE active=true AND fn_collection_point=true`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*models.Location
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		loc, err := a.getLocation(ctx, id)
		if err == nil {
			out = append(out, loc)
		}
	}
	return out, nil
}

func (a *App) listAcceptingLaboratories(ctx context.Context, sampleTypeID string) ([]*models.Location, error) {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT l.id FROM locations l
		JOIN lab_acceptances a ON a.laboratory_id = l.id AND a.accepts = true AND a.sample_type_id=$1
		WHERE l.active=true AND l.fn_laboratory=true`, sampleTypeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*models.Location
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		loc, err := a.getLocation(ctx, id)
		if err == nil {
			out = append(out, loc)
		}
	}
	// If no explicit acceptances configured, allow any active laboratory (bootstrap convenience)
	if len(out) == 0 {
		rows2, err := a.DB.Pool.Query(ctx, `SELECT id FROM locations WHERE active=true AND fn_laboratory=true`)
		if err != nil {
			return nil, err
		}
		defer rows2.Close()
		for rows2.Next() {
			var id string
			_ = rows2.Scan(&id)
			loc, err := a.getLocation(ctx, id)
			if err == nil {
				out = append(out, loc)
			}
		}
	}
	return out, nil
}

func (a *App) listActiveConnections(ctx context.Context) ([]routeHop, error) {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled
		FROM connections WHERE active=true`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []routeHop
	for rows.Next() {
		var h routeHop
		if err := rows.Scan(&h.ConnectionID, &h.FromLocationID, &h.ToLocationID, &h.TravelMinutes, &h.CostUnits, &h.Cooled); err != nil {
			return nil, err
		}
		out = append(out, h)
	}
	return out, nil
}

func (a *App) findRoute(from, to *models.Location, conns []routeHop, requiresCooled bool) *plannedRoute {
	if from.ID == to.ID {
		return &plannedRoute{Hops: nil, TotalMinutes: 0, TotalCost: 0}
	}
	// Dijkstra
	type state struct {
		node string
		min  int
		cost float64
	}
	type prevInfo struct {
		prev string
		hop  routeHop
	}
	dist := map[string]float64{}
	mins := map[string]int{}
	prev := map[string]prevInfo{}
	const inf = 1e18
	for _, c := range conns {
		dist[c.FromLocationID] = inf
		dist[c.ToLocationID] = inf
	}
	dist[from.ID] = 0
	mins[from.ID] = 0
	pq := []state{{from.ID, 0, 0}}
	visited := map[string]bool{}
	for len(pq) > 0 {
		// pop min cost
		sort.Slice(pq, func(i, j int) bool {
			if pq[i].cost == pq[j].cost {
				return pq[i].min < pq[j].min
			}
			return pq[i].cost < pq[j].cost
		})
		cur := pq[0]
		pq = pq[1:]
		if visited[cur.node] {
			continue
		}
		visited[cur.node] = true
		if cur.node == to.ID {
			break
		}
		for _, h := range conns {
			if h.FromLocationID != cur.node {
				continue
			}
			if requiresCooled && !h.Cooled {
				// allow non-cooled only if connection has no cooled flag requirement skip
				continue
			}
			nc := cur.cost + h.CostUnits
			nm := cur.min + h.TravelMinutes
			if nc < dist[h.ToLocationID] {
				dist[h.ToLocationID] = nc
				mins[h.ToLocationID] = nm
				prev[h.ToLocationID] = prevInfo{cur.node, h}
				pq = append(pq, state{h.ToLocationID, nm, nc})
			}
		}
	}
	if _, ok := prev[to.ID]; !ok && from.ID != to.ID {
		// try without cooled requirement if not found and requiresCooled was true - already filtered
		// try again without cooled filter if requiresCooled false already done
		if requiresCooled {
			// fallback: no cooled route
			return nil
		}
		return nil
	}
	if from.ID == to.ID {
		return &plannedRoute{}
	}
	if _, ok := prev[to.ID]; !ok {
		return nil
	}
	// reconstruct
	var hops []routeHop
	cur := to.ID
	for cur != from.ID {
		p, ok := prev[cur]
		if !ok {
			return nil
		}
		hops = append([]routeHop{p.hop}, hops...)
		cur = p.prev
	}
	return &plannedRoute{
		Hops:         hops,
		TotalMinutes: mins[to.ID],
		TotalCost:    dist[to.ID],
	}
}

func (a *App) routeHasCapacity(ctx context.Context, route *plannedRoute, cooled bool) bool {
	check := func(capUnits, reserved, cooledCap, cooledRes int) bool {
		if cooled {
			return (cooledCap - cooledRes) >= 1 || (capUnits-reserved) >= 1 && cooledCap == 0
		}
		return (capUnits - reserved) >= 1 || capUnits == 0 // 0 means unlimited for bootstrap
	}
	if route.CollectionNode != nil {
		c := route.CollectionNode.Capacity
		if c.CapacityUnits > 0 || c.CooledCapacityUnits > 0 {
			if !check(c.CapacityUnits, c.ReservedUnits, c.CooledCapacityUnits, c.CooledReservedUnits) {
				return false
			}
		}
	}
	if route.Laboratory != nil {
		c := route.Laboratory.Capacity
		if c.CapacityUnits > 0 || c.CooledCapacityUnits > 0 {
			if !check(c.CapacityUnits, c.ReservedUnits, c.CooledCapacityUnits, c.CooledReservedUnits) {
				return false
			}
		}
	}
	for _, h := range route.Hops {
		var cu, ru, ccu, cru int
		err := a.DB.Pool.QueryRow(ctx, `
			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
			FROM connections WHERE id=$1`, h.ConnectionID).Scan(&cu, &ru, &ccu, &cru)
		if err != nil {
			return false
		}
		if cu > 0 || ccu > 0 {
			if !check(cu, ru, ccu, cru) {
				return false
			}
		}
	}
	return true
}

func (a *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireRole(r.Context(), models.RoleRequester, models.RoleAdministrator, models.RoleDispatcher)
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = s
	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeID         *string           `json:"originNodeId"`
		SampleTypeID         string            `json:"sampleTypeId"`
		RequestedAt          string            `json:"requestedAt"`
		DeliveryDeadline     string            `json:"deliveryDeadline"`
		EarliestCollectionAt string            `json:"earliestCollectionAt"`
		LatestCollectionAt   string            `json:"latestCollectionAt"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleTypeID == "" {
		writeErr(w, badRequest("invalid_json", "sampleTypeId required"))
		return
	}
	requestedAt, err := ParseTime(req.RequestedAt)
	if err != nil || requestedAt.IsZero() {
		writeErr(w, badRequest("invalid_time", "invalid requestedAt"))
		return
	}
	deadline, err := ParseTime(req.DeliveryDeadline)
	if err != nil || deadline.IsZero() {
		writeErr(w, badRequest("invalid_deadline", "invalid deliveryDeadline"))
		return
	}
	if !deadline.After(requestedAt) {
		writeErr(w, badRequest("invalid_deadline", "deadline must be after requestedAt"))
		return
	}
	earliest := requestedAt
	if req.EarliestCollectionAt != "" {
		earliest, err = ParseTime(req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, badRequest("invalid_collection_window", "invalid earliestCollectionAt"))
			return
		}
	}
	latest := deadline
	if req.LatestCollectionAt != "" {
		latest, err = ParseTime(req.LatestCollectionAt)
		if err != nil {
			writeErr(w, badRequest("invalid_collection_window", "invalid latestCollectionAt"))
			return
		}
	}
	if latest.Before(earliest) {
		writeErr(w, badRequest("invalid_collection_window", "latest before earliest"))
		return
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		writeErr(w, badRequest("invalid_origin_type", "invalid origin type"))
		return
	}
	if _, err := a.getSampleType(r.Context(), req.SampleTypeID); err != nil {
		writeErr(w, notFound())
		return
	}
	route, reason, ver := a.checkServiceability(r.Context(), serviceabilityInput{
