	if err != nil || asg.Kind != "collection" {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	if asg.Status != "accepted" && asg.Status != "in_progress" {
		writeErr(w, httpapi.E(409, "invalid_assignment_state", "assignment not accepted"))
		return
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil || sample.ID != asg.SampleID {
		writeErr(w, notFound())
		return
	}
	// qualification check
	st, _ := a.getSampleType(r.Context(), sample.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		ok := ContainsStr(me.Qualifications, st.RequiredQualification) || ContainsStr(me.Qualifications, st.Name)
		for _, c := range me.Certifications {
			if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
				ok = true
			}
		}
		if !ok && s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.E(403, "not_qualified", "collector not qualified"))
			return
		}
	}
	now := Now()
	if req.SealedAt != "" {
		if t, err := ParseTime(req.SealedAt); err == nil {
			now = t
		}
	}
	// collection window
	if now.Before(sample.EarliestCollectionAt) || now.After(sample.LatestCollectionAt) {
		writeErr(w, httpapi.E(409, "outside_collection_window", "outside collection window"))
		return
	}
	lat, lon := sample.Origin.Latitude, sample.Origin.Longitude
	if req.Coordinate != nil {
		lat, lon = req.Coordinate.Latitude, req.Coordinate.Longitude
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='sealed', sealed=true, sealed_at=$1, current_holder_id=$2,
			latest_lat=$3, latest_lon=$4, location_recorded_at=$1 WHERE id=$5`,
		now, me.ID, lat, lon, sample.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2`, now, asg.ID)
	// activate next assignment offer
	_ = a.offerNextAssignments(r.Context(), sample.ID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "collect_and_seal_sample", "sample", sample.ID, true, nil)
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, a.sampleStateJSON(r.Context(), sample))
}

func (a *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		LaboratoryID string `json:"laboratoryId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil || asg.Kind != "laboratory" {
		writeErr(w, notFound())
		return
	}
	if asg.WorkerID == nil || *asg.WorkerID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	now := Now()
	if req.ReceivedAt != "" {
		if t, e := ParseTime(req.ReceivedAt); e == nil {
			now = t
		}
	}
	labID := req.LaboratoryID
	if labID == "" && asg.LaboratoryID != nil {
		labID = *asg.LaboratoryID
	}
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2,
			current_holder_id=$3, location_recorded_at=$2 WHERE id=$4`,
		labID, now, me.ID, sample.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$1 WHERE id=$2`, now, asg.ID)
	if sample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, *sample.ActiveJourneyID)
		_ = a.releaseCapacityForJourney(r.Context(), *sample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "confirm_laboratory_receipt", "sample", sample.ID, true, nil)
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, a.sampleLifecycleJSON(r.Context(), sample))
}

func (a *App) handleRecordLabException(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(), models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher)
	if err != nil {
		writeErr(w, err)
		return
	}
	_ = me
	var req struct {
		SampleID string `json:"sampleId"`
		Reason   string `json:"reason"`
		Kind     string `json:"kind"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	now := Now()
	kind := req.Kind
	if kind == "" {
		kind = "laboratory_rejection"
	}
	tag, err := a.DB.Pool.Exec(r.Context(), `
		UPDATE samples SET status='exception', exception_reason=$1, exception_at=$2, exception_kind=$3 WHERE id=$4`,
		req.Reason, now, kind, req.SampleID)
	if err != nil || tag.RowsAffected() == 0 {
		writeErr(w, notFound())
		return
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "record_laboratory_exception", "sample", req.SampleID, true,
		map[string]interface{}{"reason": req.Reason, "kind": kind})
	sample, _ := a.getSample(r.Context(), req.SampleID)
	writeData(w, 200, a.sampleLifecycleJSON(r.Context(), sample))
}

func (a *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		LocationID            *string `json:"locationId"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	sample, err := a.getSample(r.Context(), req.SampleID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
	}
	compliant := req.ObservedTemperatureC >= sample.TemperatureMinC &&
		req.ObservedTemperatureC <= sample.TemperatureMaxC
	if req.ContainerType != "" && sample.ContainerType != "" && req.ContainerType != sample.ContainerType {
		// frost requires cooled container etc - soft check
		if sample.ContainerType == "cooled" && req.ContainerType != "cooled" {
			compliant = false
		}
	}
	id := NewID()
	now := Now()
	_, _ = a.DB.Pool.Exec(r.Context(), `
		INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at, actor_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, compliant, now, me.ID)
	if !compliant {
		kind := "handling_violation"
		reason := "observed container or temperature outside required range"
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='exception', exception_reason=$1, exception_at=$2, exception_kind=$3 WHERE id=$4`,
			reason, now, kind, sample.ID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "record_handling_checkpoint", "sample", sample.ID, true,
		map[string]interface{}{"compliant": compliant})
	sample, _ = a.getSample(r.Context(), sample.ID)
	writeData(w, 200, map[string]interface{}{
		"checkpointId": id, "compliant": compliant, "sample": a.sampleLifecycleJSON(r.Context(), sample),
	})
}
"}

{"command":"create","path":"/workspace/backend/internal/app/journeys.go","file_text":"package app

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) planJourneyForSample(ctx context.Context, sampleID string, route *plannedRoute, presealed bool) error {
	sample, err := a.getSample(ctx, sampleID)
	if err != nil {
		return err
	}
	st, err := a.getSampleType(ctx, sample.SampleTypeID)
	if err != nil {
		return err
	}
	journeyID := NewID()
	routeMode := "direct"
	if len(route.Hops) > 1 {
		routeMode = "multi_stop"
	}
	now := Now()
	eta := route.ArrivalAt
	_, err = a.DB.Pool.Exec(ctx, `
		INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, sample_ids, assigned_worker_ids, valid)
		VALUES ($1,1,$2,'planned',$3,$4,1,$5::jsonb,'[]'::jsonb,true)`,
		journeyID, routeMode, eta, route.TotalCost, MustJSON([]string{sampleID}))
	if err != nil {
		return err
	}
	// stops
	seq := 0
	stopIDs := []string{}
	addStop := func(locID, stopType string, at time.Time, lat, lon float64) {
		sid := NewID()
		_, _ = a.DB.Pool.Exec(ctx, `
			INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, lat, lon)
			VALUES ($1,$2,$3,$4,$5,$6,0,$7,$8)`,
			sid, journeyID, locID, stopType, seq, at, lat, lon)
		stopIDs = append(stopIDs, sid)
		seq++
	}
	t := sample.EarliestCollectionAt
	if t.Before(now) {
		t = now
	}
	// origin stop (virtual if home)
	originLocID := NewID()
	if route.CollectionNode != nil {
		if sample.OriginType == "node" && sample.OriginNodeID != nil {
			originLocID = *sample.OriginNodeID
		} else {
			// use collection node as first network stop; origin is home/clinic
			addStop(route.CollectionNode.ID, "collection", t, sample.Origin.Latitude, sample.Origin.Longitude)
			originLocID = route.CollectionNode.ID
			t = t.Add(time.Duration(route.CollectionNode.HandlingMinutes) * time.Minute)
		}
	}
	prevLoc := originLocID
	for _, h := range route.Hops {
		t = t.Add(time.Duration(h.TravelMinutes) * time.Minute)
		toLoc, _ := a.getLocation(ctx, h.ToLocationID)
		lat, lon := 0.0, 0.0
		if toLoc != nil {
			lat, lon = toLoc.Coordinate.Latitude, toLoc.Coordinate.Longitude
			t = t.Add(time.Duration(toLoc.HandlingMinutes) * time.Minute)
		}
		stopType := "transfer"
		if toLoc != nil && toLoc.Functions.Laboratory {
			stopType = "laboratory"
		} else if toLoc != nil && toLoc.Functions.Hub {
			stopType = "hub"
		}
		addStop(h.ToLocationID, stopType, t, lat, lon)
		prevLoc = h.ToLocationID
	}
	_ = prevLoc

	cooledUnits := 0
	if st.RequiresCooledRoute {
		cooledUnits = 1
	}

	var collectionIDs, nodeIDs, labIDs []string
	var firstTransport, middleTransport, finalTransport *string
	asgSeq := 0

	if !presealed {
		// collection assignment
		cid := NewID()
		fromID := originLocID
		toID := originLocID
		if route.CollectionNode != nil {
			toID = route.CollectionNode.ID
		}
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id, expected_sample_type_id)
			VALUES ($1,$2,$3,'collection','pending',$4,$5,$6,$7)`,
			cid, journeyID, sampleID, asgSeq, fromID, toID, sample.SampleTypeID)
		if err != nil {
			return err
		}
		collectionIDs = append(collectionIDs, cid)
		asgSeq++
		_ = a.offerAssignment(ctx, cid)
	}

	// transport legs for each hop
	transportIDs := []string{}
	for i, h := range route.Hops {
		tid := NewID()
		from := h.FromLocationID
		to := h.ToLocationID
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id)
			VALUES ($1,$2,$3,'transport','pending',$4,$5,$6)`,
			tid, journeyID, sampleID, asgSeq, from, to)
		if err != nil {
			return err
		}
		transportIDs = append(transportIDs, tid)
		// reserve connection capacity
		_ = a.reserveCapacity(ctx, h.ConnectionID, "connection", journeyID, sampleID, 1, cooledUnits)
		asgSeq++

		// node assignment at intermediate stops
		if i < len(route.Hops)-1 {
			nid := NewID()
			_, _ = a.DB.Pool.Exec(ctx, `
				INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, node_id, to_location_id)
				VALUES ($1,$2,$3,'node','pending',$4,$5,$5)`,
				nid, journeyID, sampleID, asgSeq, to)
			nodeIDs = append(nodeIDs, nid)
			asgSeq++
		}
	}
	if len(transportIDs) > 0 {
		firstTransport = &transportIDs[0]
		finalTransport = &transportIDs[len(transportIDs)-1]
		if len(transportIDs) >= 3 {
			mid := transportIDs[len(transportIDs)/2]
			middleTransport = &mid
		} else if len(transportIDs) == 2 {
			middleTransport = &transportIDs[0]
		}
	}

	// laboratory assignment
	if route.Laboratory != nil {
		lid := NewID()
		_, err = a.DB.Pool.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, status, sequence, laboratory_id, to_location_id, expected_sample_type_id)
			VALUES ($1,$2,$3,'laboratory','pending',$4,$5,$5,$6)`,
			lid, journeyID, sampleID, asgSeq, route.Laboratory.ID, sample.SampleTypeID)
		if err != nil {
			return err
		}
		labIDs = append(labIDs, lid)
		_ = a.reserveCapacity(ctx, route.Laboratory.ID, "location", journeyID, sampleID, 1, cooledUnits)
	}
	if route.CollectionNode != nil {
		_ = a.reserveCapacity(ctx, route.CollectionNode.ID, "location", journeyID, sampleID, 1, cooledUnits)
	}

	_, err = a.DB.Pool.Exec(ctx, `
		UPDATE journeys SET collection_assignment_ids=$1::jsonb, node_assignment_ids=$2::jsonb,
			laboratory_assignment_ids=$3::jsonb, first_transport_assignment_id=$4,
			middle_transport_assignment_id=$5, final_transport_assignment_id=$6, status='active'
		WHERE id=$7`,
		MustJSON(collectionIDs), MustJSON(nodeIDs), MustJSON(labIDs),
		firstTransport, middleTransport, finalTransport, journeyID)
	if err != nil {
		return err
	}
	_, err = a.DB.Pool.Exec(ctx, `UPDATE samples SET active_journey_id=$1, status=CASE WHEN status='sealed' THEN 'in_transit' ELSE 'planned' END, target_laboratory_id=$2 WHERE id=$3`,
		journeyID, func() interface{} {
			if route.Laboratory != nil {
				return route.Laboratory.ID
			}
			return nil
		}(), sampleID)
	if err != nil {
		return err
	}
	// offer first pending non-collection if presealed
	if presealed {
		_ = a.offerNextAssignments(ctx, sampleID)
	}
	return nil
}

func (a *App) reserveCapacity(ctx context.Context, resourceID, resourceType, journeyID, sampleID string, units, cooled int) error {
	if resourceType == "location" {
		var cu, ru, ccu, cru int
		err := a.DB.Pool.QueryRow(ctx, `
			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1`, resourceID).
			Scan(&cu, &ru, &ccu, &cru)
		if err != nil {
			return err
		}
		if cu > 0 && ru+units > cu {
			return fmt.Errorf("insufficient capacity")
		}
		if ccu > 0 && cru+cooled > ccu {
			return fmt.Errorf("insufficient cooled capacity")
		}
		_, err = a.DB.Pool.Exec(ctx, `
			UPDATE locations SET reserved_units = reserved_units + $1, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$3`,
			units, cooled, resourceID)
		if err != nil {
			return err
		}
	} else if resourceType == "connection" {
		var cu, ru, ccu, cru int
		err := a.DB.Pool.QueryRow(ctx, `
			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections WHERE id=$1`, resourceID).
			Scan(&cu, &ru, &ccu, &cru)
		if err != nil {
			return err
		}
		if cu > 0 && ru+units > cu {
			return fmt.Errorf("insufficient capacity")
		}
		if ccu > 0 && cru+cooled > ccu {
			return fmt.Errorf("insufficient cooled capacity")
		}
		_, err = a.DB.Pool.Exec(ctx, `
			UPDATE connections SET reserved_units = reserved_units + $1, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$3`,
			units, cooled, resourceID)
		if err != nil {
			return err
		}
	}
	id := NewID()
	_, err := a.DB.Pool.Exec(ctx, `
		INSERT INTO capacity_reservations (id, resource_id, resource_type, journey_id, sample_id, units, cooled_units, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7,true)`,
		id, resourceID, resourceType, journeyID, sampleID, units, cooled)
	return err
}

func (a *App) releaseCapacityForJourney(ctx context.Context, journeyID string) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, resource_id, resource_type, units, cooled_units FROM capacity_reservations
		WHERE journey_id=$1 AND active=true`, journeyID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type res struct {
		id, rid, rtype string
		units, cooled  int
	}
	var list []res
	for rows.Next() {
		var r res
		_ = rows.Scan(&r.id, &r.rid, &r.rtype, &r.units, &r.cooled)
		list = append(list, r)
	}
	for _, r := range list {
		if r.rtype == "location" {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE locations SET reserved_units = GREATEST(0, reserved_units - $1),
					cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$3`,
				r.units, r.cooled, r.rid)
		} else if r.rtype == "connection" {
			_, _ = a.DB.Pool.Exec(ctx, `
				UPDATE connections SET reserved_units = GREATEST(0, reserved_units - $1),
					cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$3`,
				r.units, r.cooled, r.rid)
		}
		_, _ = a.DB.Pool.Exec(ctx, `UPDATE capacity_reservations SET active=false WHERE id=$1`, r.id)
	}
	return nil
}

func (a *App) getJourney(ctx context.Context, id string) (map[string]interface{}, error) {
	var jid string
	var parent *string
	var planVersion int
	var routeMode, status string
	var eta *time.Time
	var cost float64
	var capUsed int
	var sampleIDs, workerIDs, collIDs, nodeIDs, labIDs []byte
	var first, mid, final *string
	var valid bool
	var replan *string
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, sample_ids, assigned_worker_ids, collection_assignment_ids, node_assignment_ids,
			laboratory_assignment_ids, first_transport_assignment_id, middle_transport_assignment_id,
			final_transport_assignment_id, valid, replan_status
		FROM journeys WHERE id=$1`, id).Scan(
		&jid, &parent, &planVersion, &routeMode, &status, &eta, &cost, &capUsed,
		&sampleIDs, &workerIDs, &collIDs, &nodeIDs, &labIDs, &first, &mid, &final, &valid, &replan)
	if err != nil {
		return nil, err
	}
	stops := a.journeyStopsJSON(ctx, id)
	legs := a.journeyLegsJSON(ctx, id)
	sids := FromJSON[[]string](sampleIDs)
	if sids == nil {
		sids = []string{}
	}
	wids := FromJSON[[]string](workerIDs)
	if wids == nil {
		wids = []string{}
	}
	cids := FromJSON[[]string](collIDs)
	if cids == nil {
		cids = []string{}
	}
	nids := FromJSON[[]string](nodeIDs)
	if nids == nil {
		nids = []string{}
	}
	lids := FromJSON[[]string](labIDs)
	if lids == nil {
		lids = []string{}
	}
	capAvail := 0
	out := map[string]interface{}{
		"journeyId":                jid,
		"planVersion":              planVersion,
		"routeMode":                routeMode,
		"status":                   status,
		"totalCostUnits":           cost,
		"capacityUsed":             capUsed,
		"capacityAvailable":        capAvail,
		"sampleIds":                sids,
		"orderedStops":             stops,
		"legs":                     legs,
		"assignedWorkerIds":        wids,
		"collectionAssignmentIds":  cids,
		"nodeAssignmentIds":        nids,
		"laboratoryAssignmentIds":  lids,
		"valid":                    valid,
	}
	if parent != nil {
		out["parentJourneyId"] = *parent
	}
	if eta != nil {
		out["estimatedDeliveryAt"] = FormatTime(*eta)
	}
	if len(cids) > 0 {
		out["collectionAssignmentId"] = cids[0]
	}
	if first != nil {
		out["firstTransportAssignmentId"] = *first
	}
	if mid != nil {
		out["middleTransportAssignmentId"] = *mid
	}
	if final != nil {
		out["finalTransportAssignmentId"] = *final
	}
	if replan != nil {
		out["replanStatus"] = *replan
	}
	return out, nil
}

func (a *App) journeyStopsJSON(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, lat, lon, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, locID, stopType string
		var seq, dwell int
		var est time.Time
		var lat, lon *float64
		var completed *time.Time
		_ = rows.Scan(&id, &locID, &stopType, &seq, &est, &dwell, &lat, &lon, &completed)
		m := map[string]interface{}{
			"stopId": id, "locationId": locID, "stopType": stopType,
			"sequence": seq, "estimatedAt": FormatTime(est), "dwellMinutes": dwell,
		}
		if lat != nil && lon != nil {
			m["coordinate"] = models.Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if completed != nil {
			m["completedAt"] = FormatTime(*completed)
		}
		out = append(out, m)
	}
	return out
}

func (a *App) journeyLegsJSON(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, kind, status, sequence, from_location_id, to_location_id, node_id, laboratory_id,
			worker_id, offered_to, sample_id
		FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, kind, status, sampleID string
		var seq int
		var from, to, node, lab, worker, offered *string
		_ = rows.Scan(&id, &kind, &status, &seq, &from, &to, &node, &lab, &worker, &offered, &sampleID)
		m := map[string]interface{}{
			"assignmentId": id, "legId": id, "kind": kind, "status": status,
			"sequence": seq, "sampleId": sampleID,
		}
		if from != nil {
			m["fromLocationId"] = *from
		}
		if to != nil {
			m["toLocationId"] = *to
		}
		if node != nil {
			m["nodeId"] = *node
		}
		if lab != nil {
			m["laboratoryId"] = *lab
		}
		if worker != nil {
			m["workerId"] = *worker
		}
		if offered != nil {
			m["offeredTo"] = *offered
		}
		out = append(out, m)
	}
	return out
}

func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	// role-scoped views
	switch s.ActiveRole {
	case models.RoleRequester:
		// filter to requester journey plan
		sids := plan["sampleIds"].([]string)
		allowed := false
		for _, sid := range sids {
			sample, err := a.getSample(r.Context(), sid)
			if err == nil && sample.RequesterID == me.ID {
				allowed = true
				break
			}
		}
		if !allowed {
			writeErr(w, httpapi.ErrForbidden)
			return
		}
		out := map[string]interface{}{
			"journeyId": plan["journeyId"], "sampleIds": plan["sampleIds"], "legs": plan["legs"],
		}
		for _, k := range []string{"parentJourneyId", "planVersion", "routeMode", "status", "estimatedDeliveryAt", "totalCostUnits", "orderedStops"} {
			if v, ok := plan[k]; ok {
				out[k] = v
			}
		}
		writeData(w, 200, out)
		return
	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		// worker view - assigned legs only
		legs := a.journeyLegsJSON(r.Context(), req.JourneyID)
		filtered := []map[string]interface{}{}
		asgIDs := []string{}
		for _, leg := range legs {
			wid, _ := leg["workerId"].(string)
			off, _ := leg["offeredTo"].(string)
			if wid == me.ID || off == me.ID {
				filtered = append(filtered, leg)
				if id, ok := leg["assignmentId"].(string); ok {
					asgIDs = append(asgIDs, id)
				}
			}
		}
		out := map[string]interface{}{
			"journeyId": plan["journeyId"], "planVersion": plan["planVersion"],
			"routeMode": plan["routeMode"], "status": plan["status"],
			"scope": "assigned_legs", "assignmentIds": asgIDs,
			"sampleIds": plan["sampleIds"], "legs": filtered, "orderedStops": plan["orderedStops"],
			"collectionAssignmentIds": plan["collectionAssignmentIds"],
			"nodeAssignmentIds":       plan["nodeAssignmentIds"],
			"laboratoryAssignmentIds": plan["laboratoryAssignmentIds"],
			"assignedWorkerIds":       plan["assignedWorkerIds"],
		}
		if v, ok := plan["parentJourneyId"]; ok {
			out["parentJourneyId"] = v
		}
		if v, ok := plan["estimatedDeliveryAt"]; ok {
			out["estimatedDeliveryAt"] = v
		}
		writeData(w, 200, out)
		return
	default:
		writeData(w, 200, plan)
	}
}

func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID   string `json:"journeyId"`
		PlanVersion *int   `json:"planVersion"`
		Reason      string `json:"reason"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if req.PlanVersion != nil && plan["planVersion"].(int) != *req.PlanVersion {
		writeErr(w, httpapi.ErrConcurrent)
		return
	}
	// cancel unfinished assignments only
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, req.JourneyID)
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='cancelled', plan_version = plan_version + 1 WHERE id=$1`, req.JourneyID)
	_ = a.releaseCapacityForJourney(r.Context(), req.JourneyID)
	sids := plan["sampleIds"].([]string)
	for _, sid := range sids {
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','cancelled')`, sid)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
	plan, _ = a.getJourney(r.Context(), req.JourneyID)
	writeData(w, 200, plan)
}

func (a *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID   string `json:"journeyId"`
		PlanVersion *int   `json:"planVersion"`
		Reason      string `json:"reason"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if req.PlanVersion != nil && plan["planVersion"].(int) != *req.PlanVersion {
		writeErr(w, httpapi.ErrConcurrent)
		return
	}
	sids := plan["sampleIds"].([]string)
	if len(sids) == 0 {
		writeErr(w, badRequest("invalid_json", "no samples"))
		return
	}
	// cancel unfinished, keep completed
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered')`, req.JourneyID)
	_ = a.releaseCapacityForJourney(r.Context(), req.JourneyID)
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE journeys SET status='superseded', plan_version = plan_version + 1, replan_status='replaced' WHERE id=$1`, req.JourneyID)

	sample, err := a.getSample(r.Context(), sids[0])
	if err != nil {
		writeErr(w, notFound())
		return
	}
	route, reason, _ := a.checkServiceability(r.Context(), serviceabilityInput{
		Origin: sample.Origin, OriginType: sample.OriginType, OriginNodeID: sample.OriginNodeID,
		SampleTypeID: sample.SampleTypeID, RequestedAt: Now(), DeliveryDeadline: sample.DeliveryDeadline,
		EarliestCollectionAt: Now(), LatestCollectionAt: sample.LatestCollectionAt,
	})
	if reason != "serviceable" || route == nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `
			UPDATE samples SET status='expired', exception_reason=$1, exception_kind='deadline_unreachable', exception_at=$2 WHERE id=$3`,
			reason, Now(), sample.ID)
		a.audit(r.Context(), s.UserID, s.ActiveRole, "reroute_journey", "journey", req.JourneyID, false, map[string]interface{}{"reason": reason})
		writeErr(w, httpapi.E(409, "deadline_unreachable", "no valid route"))
		return
	}
	presealed := sample.Sealed
	if err := a.planJourneyForSample(r.Context(), sample.ID, route, presealed); err != nil {
		writeErr(w, errInternal)
		return
	}
	// mark parent
	newSample, _ := a.getSample(r.Context(), sample.ID)
	if newSample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, req.JourneyID, *newSample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, nil)
	if newSample.ActiveJourneyID != nil {
		plan, _ = a.getJourney(r.Context(), *newSample.ActiveJourneyID)
	}
	writeData(w, 200, plan)
}

func (a *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
