func (a *App) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyID string   `json:"journeyId"`
		SampleIDs []string `json:"sampleIds"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	plan, err := a.getJourney(r.Context(), req.JourneyID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if len(req.SampleIDs) == 0 {
		writeErr(w, badRequest("invalid_json", "sampleIds required"))
		return
	}
	// create new journey for split samples by replan
	sample, err := a.getSample(r.Context(), req.SampleIDs[0])
	if err != nil {
		writeErr(w, notFound())
		return
	}
	route, reason, _ := a.checkServiceability(r.Context(), serviceabilityInput{
		Origin: sample.Origin, OriginType: sample.OriginType, OriginNodeID: sample.OriginNodeID,
		SampleTypeID: sample.SampleTypeID, RequestedAt: Now(), DeliveryDeadline: sample.DeliveryDeadline,
		EarliestCollectionAt: Now(), LatestCollectionAt: sample.LatestCollectionAt,
	})
	if reason != "serviceable" {
		writeErr(w, httpapi.E(409, "no_route", reason))
		return
	}
	// remove samples from old journey list
	oldIDs := plan["sampleIds"].([]string)
	remain := []string{}
	for _, id := range oldIDs {
		if !ContainsStr(req.SampleIDs, id) {
			remain = append(remain, id)
		}
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET sample_ids=$1::jsonb, plan_version=plan_version+1 WHERE id=$2`, MustJSON(remain), req.JourneyID)
	_ = a.planJourneyForSample(r.Context(), sample.ID, route, sample.Sealed)
	newSample, _ := a.getSample(r.Context(), sample.ID)
	if newSample.ActiveJourneyID != nil {
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, req.JourneyID, *newSample.ActiveJourneyID)
	}
	a.audit(r.Context(), s.UserID, s.ActiveRole, "split_journey", "journey", req.JourneyID, true, nil)
	if newSample.ActiveJourneyID != nil {
		plan, _ = a.getJourney(r.Context(), *newSample.ActiveJourneyID)
	}
	writeData(w, 200, plan)
}

func (a *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	s, _, err := a.requireAdminOrDispatcher(r.Context())
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		JourneyIDs []string `json:"journeyIds"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if len(req.JourneyIDs) < 2 {
		writeErr(w, badRequest("invalid_json", "need at least 2 journeys"))
		return
	}
	// merge sample ids into first journey
	primary := req.JourneyIDs[0]
	plan, err := a.getJourney(r.Context(), primary)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	all := append([]string{}, plan["sampleIds"].([]string)...)
	for _, jid := range req.JourneyIDs[1:] {
		p, err := a.getJourney(r.Context(), jid)
		if err != nil {
			continue
		}
		// validate compatibility of samples
		for _, sid := range p["sampleIds"].([]string) {
			sample, err := a.getSample(r.Context(), sid)
			if err != nil {
				continue
			}
			st, _ := a.getSampleType(r.Context(), sample.SampleTypeID)
			if st != nil && !st.BatchingAllowed {
				writeErr(w, httpapi.E(409, "batching_not_allowed", "pulse cannot batch"))
				return
			}
			all = append(all, sid)
			_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, primary, sid)
		}
		_, _ = a.DB.Pool.Exec(r.Context(), `UPDATE journeys SET status='merged', plan_version=plan_version+1 WHERE id=$1`, jid)
	}
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE journeys SET sample_ids=$1::jsonb, route_mode='batched', plan_version=plan_version+1 WHERE id=$2`,
		MustJSON(all), primary)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "merge_journeys", "journey", primary, true, nil)
	plan, _ = a.getJourney(r.Context(), primary)
	writeData(w, 200, plan)
}
"}

{"command":"create","path":"/workspace/backend/internal/app/assignments.go","file_text":"package app

import (
	"context"
	"net/http"
	"time"

	"labsample/internal/httpapi"
	"labsample/internal/models"
)

func (a *App) getAssignment(ctx context.Context, id string) (*models.Assignment, error) {
	asg := &models.Assignment{}
	var from, to, node, lab, worker, offered, expected *string
	var offerExp, accepted, completed *time.Time
	var declined []byte
	err := a.DB.Pool.QueryRow(ctx, `
		SELECT id, journey_id, sample_id, kind, status, sequence, from_location_id, to_location_id,
			node_id, laboratory_id, worker_id, offered_to, offer_expires_at, accepted_at, completed_at,
			declined_by, expected_sample_type_id, created_at
		FROM assignments WHERE id=$1`, id).Scan(
		&asg.ID, &asg.JourneyID, &asg.SampleID, &asg.Kind, &asg.Status, &asg.Sequence,
		&from, &to, &node, &lab, &worker, &offered, &offerExp, &accepted, &completed,
		&declined, &expected, &asg.CreatedAt)
	if err != nil {
		return nil, err
	}
	asg.FromLocationID = from
	asg.ToLocationID = to
	asg.NodeID = node
	asg.LaboratoryID = lab
	asg.WorkerID = worker
	asg.OfferedTo = offered
	asg.OfferExpiresAt = offerExp
	asg.AcceptedAt = accepted
	asg.CompletedAt = completed
	asg.DeclinedBy = FromJSON[[]string](declined)
	if asg.DeclinedBy == nil {
		asg.DeclinedBy = []string{}
	}
	asg.ExpectedSampleType = expected
	return asg, nil
}

func (a *App) offerAssignment(ctx context.Context, assignmentID string) error {
	asg, err := a.getAssignment(ctx, assignmentID)
	if err != nil {
		return err
	}
	if asg.Status != "pending" && asg.Status != "offered" {
		return nil
	}
	workerID, err := a.pickWorker(ctx, asg)
	if err != nil || workerID == "" {
		// no worker - if long enough, flag exception
		return a.maybeFlagNoWorker(ctx, asg)
	}
	exp := Now().Add(time.Duration(a.Cfg.OfferTimeoutSec) * time.Second)
	_, err = a.DB.Pool.Exec(ctx, `
		UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2 WHERE id=$3`,
		workerID, exp, assignmentID)
	if err != nil {
		return err
	}
	a.publishEvent(ctx, "assignment_offered", "assignment", assignmentID, map[string]interface{}{
		"workerId": workerID, "kind": asg.Kind, "sampleId": asg.SampleID,
	})
	return nil
}

func (a *App) maybeFlagNoWorker(ctx context.Context, asg *models.Assignment) error {
	// if pending/offered for > offer timeout * 3 and no worker, flag
	if time.Since(asg.CreatedAt) < time.Duration(a.Cfg.OfferTimeoutSec*3)*time.Second {
		return nil
	}
	_, _ = a.DB.Pool.Exec(ctx, `
		UPDATE samples SET status='exception', exception_reason=$1, exception_kind='no_qualified_worker', exception_at=$2
		WHERE id=$3 AND status NOT IN ('received','cancelled','exception')`,
		"no qualified worker available", Now(), asg.SampleID)
	return nil
}

func (a *App) pickWorker(ctx context.Context, asg *models.Assignment) (string, error) {
	var role string
	switch asg.Kind {
	case "collection":
		role = models.RoleCollectionProfessional
	case "transport":
		role = models.RoleDeliveryPartner
	case "node":
		role = models.RoleNodeHandler
	case "laboratory":
		role = models.RoleLaboratoryTeam
	default:
		return "", nil
	}
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, roles, qualifications, certifications, available, capacity_units,
			decline_penalty_until, assigned_location_id
		FROM users WHERE active=true AND available=true`)
	if err != nil {
		return "", err
	}
	defer rows.Close()

	type cand struct {
		id       string
		workload int
		penalty  bool
	}
	var cands []cand
	now := Now()
	for rows.Next() {
		var id string
		var roles, quals, certs []byte
		var avail bool
		var cap int
		var penalty *time.Time
		var assigned *string
		if err := rows.Scan(&id, &roles, &quals, &certs, &avail, &cap, &penalty, &assigned); err != nil {
			continue
		}
		rlist := FromJSON[[]string](roles)
		if !ContainsStr(rlist, role) {
			continue
		}
		if ContainsStr(asg.DeclinedBy, id) {
			// temporary lower priority but still eligible after penalty
			if penalty != nil && penalty.After(now) {
				continue
			}
		}
		if asg.Kind == "node" || asg.Kind == "laboratory" {
			locID := asg.NodeID
			if asg.Kind == "laboratory" {
				locID = asg.LaboratoryID
			}
			if locID == nil || assigned == nil || *assigned != *locID {
				continue
			}
		}
		if asg.Kind == "collection" && asg.ExpectedSampleType != nil {
			st, err := a.getSampleType(ctx, *asg.ExpectedSampleType)
			if err == nil && st.QualifiedCollectorRequired {
				qlist := FromJSON[[]string](quals)
				clist := FromJSON[[]models.Certification](certs)
				ok := ContainsStr(qlist, st.RequiredQualification) || ContainsStr(qlist, st.Name)
				for _, c := range clist {
					if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
						ok = true
					}
				}
				if !ok {
					continue
				}
			}
		}
		// workload
		var wl int
		_ = a.DB.Pool.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE (worker_id=$1 OR offered_to=$1) AND status IN ('offered','accepted','in_progress')`, id).Scan(&wl)
		if cap > 0 && wl >= cap {
			continue
		}
		cands = append(cands, cand{id: id, workload: wl, penalty: penalty != nil && penalty.After(now)})
	}
	if len(cands) == 0 {
		return "", nil
	}
	// pick lowest workload, non-penalty first
	best := cands[0]
	for _, c := range cands[1:] {
		if best.penalty && !c.penalty {
			best = c
			continue
		}
		if c.penalty == best.penalty && c.workload < best.workload {
			best = c
		}
	}
	return best.id, nil
}

func (a *App) offerNextAssignments(ctx context.Context, sampleID string) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, kind, status, sequence FROM assignments
		WHERE sample_id=$1 ORDER BY sequence`, sampleID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type row struct {
		id, kind, status string
		seq              int
	}
	var list []row
	for rows.Next() {
		var r row
		_ = rows.Scan(&r.id, &r.kind, &r.status, &r.seq)
		list = append(list, r)
	}
	// find first incomplete; if previous completed, offer it
	for i, r := range list {
		if r.status == "completed" || r.status == "cancelled" {
			continue
		}
		if r.status == "pending" {
			// ensure previous done (except first)
			if i > 0 {
				prev := list[i-1]
				if prev.status != "completed" && prev.status != "cancelled" {
					// wait; but if prev is accepted/in_progress for transport chain after seal, ok to offer transport after collection complete only
					return nil
				}
			}
			return a.offerAssignment(ctx, r.id)
		}
		if r.status == "offered" || r.status == "accepted" || r.status == "in_progress" {
			return nil
		}
	}
	return nil
}

func (a *App) expireOffers(ctx context.Context) error {
	rows, err := a.DB.Pool.Query(ctx, `
		SELECT id, offered_to, declined_by FROM assignments
		WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < NOW()`)
	if err != nil {
		return err
	}
	defer rows.Close()
	type exp struct {
		id, offered string
		declined    []byte
	}
	var list []exp
	for rows.Next() {
		var e exp
		var offered *string
		_ = rows.Scan(&e.id, &offered, &e.declined)
		if offered != nil {
			e.offered = *offered
		}
		list = append(list, e)
	}
	for _, e := range list {
		declined := FromJSON[[]string](e.declined)
		if declined == nil {
			declined = []string{}
		}
		if e.offered != "" && !ContainsStr(declined, e.offered) {
			declined = append(declined, e.offered)
		}
		_, _ = a.DB.Pool.Exec(ctx, `
			UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$1::jsonb WHERE id=$2`,
			MustJSON(declined), e.id)
		// soft penalty
		if e.offered != "" {
			until := Now().Add(10 * time.Minute)
			_, _ = a.DB.Pool.Exec(ctx, `UPDATE users SET decline_penalty_until=$1 WHERE id=$2`, until, e.offered)
		}
		_ = a.offerAssignment(ctx, e.id)
	}
	return nil
}

func (a *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
	if err != nil {
		writeErr(w, err)
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := decode(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	asg, err := a.getAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		writeErr(w, notFound())
		return
	}
	if asg.Status != "offered" {
		writeErr(w, httpapi.E(409, "invalid_assignment_state", "not offered"))
		return
	}
	if asg.OfferedTo == nil || *asg.OfferedTo != me.ID {
		if s.ActiveRole != models.RoleAdministrator {
			writeErr(w, httpapi.E(403, "not_offered_to_user", "assignment offered to another worker"))
			return
		}
	}
	now := Now()
	_, err = a.DB.Pool.Exec(r.Context(), `
		UPDATE assignments SET status='accepted', worker_id=$1, accepted_at=$2, offered_to=$1 WHERE id=$3`,
		me.ID, now, asg.ID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	// add worker to journey
	_, _ = a.DB.Pool.Exec(r.Context(), `
		UPDATE journeys SET assigned_worker_ids = (
			SELECT COALESCE(jsonb_agg(DISTINCT x), '[]'::jsonb) FROM (
				SELECT jsonb_array_elements_text(assigned_worker_ids) AS x
				UNION SELECT $1
			) s
		) WHERE id=$2`, me.ID, asg.JourneyID)
	a.audit(r.Context(), s.UserID, s.ActiveRole, "accept_assignment", "assignment", asg.ID, true, nil)
	asg, _ = a.getAssignment(r.Context(), asg.ID)
	writeData(w, 200, a.assignmentJSON(asg))
}

func (a *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	s, me, err := a.requireRole(r.Context(),
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam)
