				}
				switch status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "requested", "planned", "unserviceable":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	case models.RoleAdministrator, models.RoleDispatcher:
		rows, err := a.DB.Pool.Query(r.Context(), `
			SELECT id, status, request_id, delivery_deadline, active_journey_id FROM samples ORDER BY created_at DESC LIMIT 500`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status, reqID string
				var deadline time.Time
				var jid *string
				_ = rows.Scan(&id, &status, &reqID, &deadline, &jid)
				item := map[string]interface{}{
					"type": "sample", "sampleId": id, "requestId": reqID, "status": status,
					"deliveryDeadline": FormatTime(deadline),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				switch status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "requested", "planned", "unserviceable", "exception":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	default:
		// worker assignments
		rows, err := a.DB.Pool.Query(r.Context(), `
			SELECT id, journey_id, sample_id, kind, status, sequence FROM assignments
			WHERE worker_id=$1 OR offered_to=$1 ORDER BY created_at DESC LIMIT 500`, me.ID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, jid, sid, kind, status string
				var seq int
				_ = rows.Scan(&id, &jid, &sid, &kind, &status, &seq)
