# Append seed network to app.go Bootstrap via new file seed.go
seed = r'''package app

import (
	"context"
	"log"
)

// seedBangaloreNetwork creates a default operational network around Bangalore
// when no locations exist yet. Safe to call repeatedly.
func (a *App) seedBangaloreNetwork(ctx context.Context) error {
	var n int
	if err := a.DB.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM locations`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	log.Printf("seeding Bangalore demo network")

	type loc struct {
		id, name string
		lat, lon float64
		cp, tp, hub, lab bool
		accept            []string
	}
	// Central Bangalore points within ~5km of each other for serviceability
	locs := []loc{
		{NewID(), "Indiranagar Collection Centre", 12.9784, 77.6408, true, true, false, false, nil},
		{NewID(), "Koramangala Hub", 12.9352, 77.6245, true, true, true, false, nil},
		{NewID(), "MG Road Transfer", 12.9750, 77.6063, false, true, false, false, nil},
		{NewID(), "City Lab Whitefield Gate", 12.9698, 77.7499, false, true, false, true, []string{"Amber", "Indigo", "Frost", "Pulse"}},
		{NewID(), "Central Diagnostics Lab", 12.9716, 77.5946, true, true, true, true, []string{"Amber", "Indigo", "Frost", "Pulse"}},
	}

	for _, l := range locs {
		_, err := a.DB.Pool.Exec(ctx, `
			INSERT INTO locations (
				id, name, latitude, longitude, coverage_km, handling_minutes, active,
				fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
				capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
			VALUES ($1,$2,$3,$4,5,10,true,$5,$6,$7,$8,100,0,50,0)`,
			l.id, l.name, l.lat, l.lon, l.cp, l.tp, l.hub, l.lab)
		if err != nil {
			return err
		}
	}

	// connections between them (bidirectional)
	pairs := []struct{ a, b int; mins int; cooled bool }{
		{0, 1, 25, true},
		{0, 2, 20, true},
		{0, 4, 15, true},
		{1, 2, 20, true},
		{1, 3, 35, true},
		{1, 4, 20, true},
		{2, 4, 12, true},
		{2, 3, 40, true},
		{4, 3, 45, true},
	}
	for _, p := range pairs {
		for _, dir := range [][2]int{{p.a, p.b}, {p.b, p.a}} {
			id := NewID()
			_, err := a.DB.Pool.Exec(ctx, `
				INSERT INTO connections (
					id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
					capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
				VALUES ($1,$2,$3,$4,$5,$6,true,50,0,25,0)`,
				id, locs[dir[0]].id, locs[dir[1]].id, p.mins, float64(p.mins), p.cooled)
			if err != nil {
				return err
			}
		}
	}

	// lab acceptances for all sample types at lab locations
	typeRows, err := a.DB.Pool.Query(ctx, `SELECT id, name FROM sample_types`)
	if err != nil {
		return err
	}
	defer typeRows.Close()
	type typeRow struct{ id, name string }
	var types []typeRow
	for typeRows.Next() {
		var t typeRow
		_ = typeRows.Scan(&t.id, &t.name)
		types = append(types, t)
	}
	for _, l := range locs {
		if !l.lab {
			continue
		}
		for _, t := range types {
			_, _ = a.DB.Pool.Exec(ctx, `
				INSERT INTO lab_acceptances (location_id, sample_type_id, accepted)
				VALUES ($1,$2,true)
				ON CONFLICT (location_id, sample_type_id) DO UPDATE SET accepted=true`,
				l.id, t.id)
		}
	}

	return a.recomputeServiceability(ctx)
}
'''
